        var r = new CashMachine(d).Execute(Acc(100, 30), D(N(1, 1, 1)));

        Assert.Equal(new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, Acc(100, 30)), r);
        Assert.Equal(N(1, 1, 1), d.Stock);
    }

